reference_solution:
def valid_brackets(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for character in text:
        if character in "([{":
            stack.append(character)
        elif not stack or stack.pop() != pairs.get(character):
            return False
    return not stack

